static esp_err_t sc2336_soft_reset(esp_cam_sensor_device_t *dev)
{
    esp_err_t ret = sc2336_set_reg_bits(dev->sccb_handle, 0x0103, 0, 1, 0x01);
    delay_ms(5);
    return ret;
}

static esp_err_t sc2336_get_sensor_id(esp_cam_sensor_device_t *dev, esp_cam_sensor_id_t *id)
{
    esp_err_t ret = ESP_FAIL;
    uint8_t pid_h, pid_l;

    ret = sc2336_read(dev->sccb_handle, SC2336_REG_SENSOR_ID_H, &pid_h);
    if (ret != ESP_OK) {
        return ret;
    }
    ret = sc2336_read(dev->sccb_handle, SC2336_REG_SENSOR_ID_L, &pid_l);
    if (ret != ESP_OK) {
        return ret;
    }
    id->pid = (pid_h << 8) | pid_l;

    return ret;
}

static esp_err_t sc2336_set_stream(esp_cam_sensor_device_t *dev, int enable)
{
    esp_err_t ret = ESP_FAIL;
    ret = sc2336_write(dev->sccb_handle, SC2336_REG_SLEEP_MODE, enable ? 0x01 : 0x00);

    dev->stream_status = enable;

static esp_err_t sc2336_set_reg_bits(esp_sccb_io_handle_t sccb_handle, uint16_t reg, uint8_t offset, uint8_t length, uint8_t value)
{
    esp_err_t ret = ESP_OK;
    uint8_t reg_data = 0;

    ret = sc2336_read(sccb_handle, reg, &reg_data);
    if (ret != ESP_OK) {
        return ret;
    }
    uint8_t mask = ((1 << length) - 1) << offset;
    value = (reg_data & ~mask) | ((value << offset) & mask);
    ret = sc2336_write(sccb_handle, reg, value);
    return ret;
}

static esp_err_t sc2336_set_test_pattern(esp_cam_sensor_device_t *dev, int enable)
{

  int ret = OK;
  struct esp_i2c_priv_s *priv = (struct esp_i2c_priv_s *)dev;
#ifdef CONFIG_I2C_TRACE
  uint32_t status = 0;
#endif

  i2cinfo("Starting transfer request of %d message(s):\n", count);

  DEBUGASSERT(count > 0);

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

#ifdef CONFIG_PM
  esp_pm_lock_acquire(priv->pm_lock);
#endif

  if (priv->i2cstate != I2CSTATE_IDLE)
    {
      esp_i2c_reset_fsmc(priv);
      priv->i2cstate = I2CSTATE_IDLE;
    }

  priv->msgv = msgs;

  for (int i = 0; i < count; i++)
    {
      esp_i2c_reset_fifo(priv);

      priv->bytes = 0;
      priv->msgid = i;
      priv->ready_read = false;
      priv->error = 0;
      priv->i2cstate = I2CSTATE_PROC;

      i2cinfo("Sending message %" PRIu8 "...\n", priv->msgid);

      esp_i2c_init_clock(priv, msgs[i].frequency);
#ifdef CONFIG_I2C_TRACE
      status = GET_STATUS(priv->ctx->dev);
#endif
#ifndef CONFIG_I2C_POLLED
      if ((msgs[i].flags & I2C_M_NOSTART) != 0)
        {
          esp_i2c_traceevent(priv, I2CEVENT_SENDBYTE, priv->bytes, status);
          esp_i2c_senddata(priv);

          if (priv->bytes == msgs[i].length)
            {
              priv->i2cstate = I2CSTATE_STOP;
              if ((msgs[i].flags & I2C_M_NOSTOP) != 0)
                {
                  priv->i2cstate = I2CSTATE_FINISH;
                }
            }
        }
      else
#endif
        {
          /* Reset I2C trace logic */

          esp_i2c_tracereset(priv);

          esp_i2c_traceevent(priv, I2CEVENT_SENDADDR, msgs[i].addr, status);

          esp_i2c_sendstart(priv);
        }

#ifndef CONFIG_I2C_POLLED
      if (esp_i2c_sem_waitdone(priv) < 0)
        {
          i2cerr("Message %" PRIu8 " timed out.\n", priv->msgid);
          ret = -ETIMEDOUT;
          break;
        }
      else
        {
          if (priv->error != 0)
            {
              i2cerr("Transfer error %" PRIu32 "\n", priv->error);
              ret = -EIO;
              break;
            }
          else
            {
              priv->i2cstate = I2CSTATE_IDLE;
              ret = OK;
            }
        }
#else
      ret = esp_i2c_polling_waitdone(priv);
      if (ret < 0)
        {
          if (ret == -ETIMEDOUT)
            {
              break;
            }
          else
            {
              ret = -EIO;
              break;
            }
        }
      else
        {
          /* Successful transfer, update the I2C state to idle */

          priv->i2cstate = I2CSTATE_IDLE;
          ret = OK;
        }
#endif

        i2cinfo("Message %" PRIu8 " transfer complete.\n", priv->msgid);
    }

  /* Dump the trace result */

  esp_i2c_tracedump(priv);

  esp_i2c_tracedump(priv);
#ifdef CONFIG_PM
  esp_pm_lock_release(priv->pm_lock);
#endif
  nxmutex_unlock(&priv->lock);

  return ret;
}

/****************************************************************************
 * Name: esp_i2c_clear_bus
 *
 * Description:
 *   Clear I2C bus, when the slave is stuck in a deadlock and keeps pulling
 *   the bus low, master can control the SCL bus to generate 9 CLKs.
 *
 * Parameters:
 *   priv - Pointer to the internal driver state structure.
 *
 ****************************************************************************/

#ifdef CONFIG_I2C_RESET
static void esp_i2c_clear_bus(struct esp_i2c_priv_s *priv)
{
  i2c_ll_master_clr_bus(priv->ctx->dev,
                        I2C_LL_RESET_SLV_SCL_PULSE_NUM_DEFAULT, true);

  /* Wait for bus clear done or timeout */

  clock_t start = clock_systime_ticks();
  clock_t timeout = start + MSEC2TICK(I2C_CLR_BUS_TIMEOUT_MS);
  while (i2c_ll_master_is_bus_clear_done(priv->ctx->dev))
    {
      if (clock_systime_ticks() >= timeout)
        {
          i2cerr("ERROR: clear bus failed.\n");
          i2c_ll_master_clr_bus(priv->ctx->dev, 0, false);
          break;
        }
    }

  i2c_ll_update(priv->ctx->dev);
}
#endif

