    NAME ${CONFIG_EXAMPLES_JPEGENC_PROGNAME}
    SRCS jpegenc_main.c
    STACKSIZE ${CONFIG_EXAMPLES_JPEGENC_STACKSIZE}
    PRIORITY ${CONFIG_EXAMPLES_JPEGENC_PRIORITY})
