 * Name: esp_i2cbus_initialize
 *
 * Description:
 *   Initialize the selected I2C port. And return a pointer to an unique
 *   instance of struct i2c_master_s. This function may be called to obtain
 *   multiple instances of the interface, each of which may be set up with a
 *   different frequency and slave address.
 *
 * Parameters:
 *   port - Port number of the I2C interface to be initialized.
 *
 * Returned Value:
 *   Pointer to valid I2C device structure is returned on success.
 *   A NULL pointer is returned on failure.
 *
 ****************************************************************************/

struct i2c_master_s *esp_i2cbus_initialize(int port)
{
  struct esp_i2c_priv_s *priv;
  int ret;
#ifdef CONFIG_PM
  esp_pm_lock_type_t pm_lock_type = ESP_PM_NO_LIGHT_SLEEP;
#endif

  switch (port)
    {
#ifdef CONFIG_ESPRESSIF_I2C0_MASTER_MODE
    case ESPRESSIF_I2C0:
      priv = &esp_i2c0_priv;
      break;
#endif
#ifdef CONFIG_ESPRESSIF_I2C1_MASTER_MODE
    case ESPRESSIF_I2C1:
      priv = &esp_i2c1_priv;
      break;
#endif
#ifdef CONFIG_ESPRESSIF_LP_I2C0
    case ESPRESSIF_LP_I2C0:
      priv = &esp_lp_i2c0_priv;
      break;
#endif
    default:
      return NULL;
    }

  nxmutex_lock(&priv->lock);

  if (priv->refs++ != 0)
    {
      nxmutex_unlock(&priv->lock);

      i2cinfo("Returning previously initialized I2C bus. "
              "Handler: %p\n", priv);

      return (struct i2c_master_s *)priv;
    }

#ifdef CONFIG_PM
#  if SOC_I2C_SUPPORT_RTC
  if (I2C_CLK_SRC_DEFAULT == I2C_CLK_SRC_RC_FAST)
    {
      pm_lock_type = ESP_PM_NO_LIGHT_SLEEP;
    }
#  endif

#  if SOC_I2C_SUPPORT_APB
  if (I2C_CLK_SRC_DEFAULT == I2C_CLK_SRC_APB)
    {
      pm_lock_type = ESP_PM_APB_FREQ_MAX;
    }

