{
  if (nr_datafmts < 1 || datafmts == NULL)
    {
      return -EINVAL;
    }

  /* We only support RGB565 at 1024x600 */

  if (datafmts[0].width != ESP_CAM_HRES ||
      datafmts[0].height != ESP_CAM_VRES ||
      datafmts[0].pixelformat != IMGDATA_PIX_FMT_RGB565)
    {
      return -EINVAL;
    }

  /* Fill in the real frame size.  The V4L2 layer copies the sizeimage it
   * receives from S_FMT verbatim, and userspace tools commonly leave it 0
   * and rely on the driver to report the actual buffer size.  If we do not
   * fix it here, the app allocates a zero-length buffer and the CSI DMA
   * writes past it -> memory corruption / crash when streaming starts.
   */

  datafmts[0].sizeimage = ESP_CAM_HRES * ESP_CAM_VRES * 2;  /* RGB565 */

  return OK;
}

