这是问题。ISR 里 xQueueSendFromISR 不能调用会阻塞的函数。NuttX 里 ISR 上下文不能 sem_wait。

解决方案:ISR 里用关中断(spin_lock_irqsave)保护索引,不用 mutex。
```c
BaseType_t xQueueSendFromISR(Queue_t *q, const void *item, BaseType_t *woken) {
    irqstate_t flags = spin_lock_irqsave(NULL);  // 或 enter_critical_section
    if (q->count >= q->length) { spin_unlock_irqrestore(NULL, flags); return pdFALSE; }
    memcpy(...);
    q->count++;
    spin_unlock_irqrestore(NULL, flags);
    nxsem_post(&q->items);
    if (woken) *woken = pdTRUE;
    return pdTRUE;
}
```

xQueueReceive(在任务上下文):
```c
BaseType_t xQueueReceive(Queue_t *q, void *buf, TickType_t ticks) {
    if (ticks == portMAX_DELAY) {
        if (nxsem_wait_uninterruptible(&q->items) != 0) return pdFALSE;
    } else {
        if (nxsem_tickwait(&q->items, ticks) != 0) return pdFALSE;
    }
    irqstate_t flags = spin_lock_irqsave(NULL);
    memcpy(buf, ...);
    q->count--;
    spin_unlock_irqrestore(NULL, flags);
    return pdTRUE;
}
```

xSemaphoreTake:
```c
BaseType_t xSemaphoreTake(sem_t *s, TickType_t ticks) {
    if (ticks == portMAX_DELAY) return (nxsem_wait_uninterruptible(s) == 0) ? pdTRUE : pdFALSE;
    return (nxsem_tickwait(s, ticks) == 0) ? pdTRUE : pdFALSE;
}
```

