```c
/****************************************************************************
 * arch/risc-v/src/common/espressif/freertos/portmacro.h
 *
 * Minimal FreeRTOS port layer shim for the ESP32-P4 JPEG encoder HAL.
 * Maps the small set of FreeRTOS types/macros used by esp-hal-3rdparty
 * upper_hal_jpeg / upper_hal_dma onto NuttX primitives.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __FREERTOS_PORTMACRO_H
#define __FREERTOS_PORTMACRO_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <nuttx/spinlock.h>

/* FreeRTOS base types */
typedef int32_t BaseType_t;
typedef uint32_t UBaseType_t;
typedef uint32_t TickType_t;

#define portMAX_DELAY            (TickType_t)0xffffffffUL

/* portMUX_TYPE must be rspinlock_t so that dma2d.c can feed the same
 * spinlock to esp_os_enter_critical_safe() (OS_SPINLOCK_TYPE is rspinlock_t).
 */
typedef rspinlock_t portMUX_TYPE;
#define portMUX_INITIALIZER_UNLOCKED  RSPINLOCK_INITIALIZER

/* ISR wake-up: NuttX schedules after nxsem_post() from ISR, no explicit
 * yield marker needed.
 */
#define portYIELD_FROM_ISR(x)    do { (void)(x); } while (0)

/* Critical sections are handled through the esp_os_* helpers (platform/os.h)
 * in the HAL code; keep the classic FreeRTOS macros defined for safety.
 */
#define portENTER_CRITICAL()               enter_critical_section()
#define portEXIT_CRITICAL()                leave_critical_section(0)
#define portSET_INTERRUPT_MASK_FROM_ISR()  0
#define portCLEAR_INTERRUPT_MASK_FROM_ISR(x) do { (void)(x); } while (0)

#endif /* __FREERTOS_PORTMACRO_H */
```

