#include "freertos/FreeRTOS.h"
#include "freertos/queue.h"
#include <nuttx/irq.h>
#include <nuttx/semaphore.h>
#include <nuttx/kmalloc.h>
#include <string.h>

struct QueueDefinition
{
  uint8_t *storage;
  uint32_t item_size;
  uint32_t length;
  uint32_t head;
  uint32_t tail;
  uint32_t count;
  sem_t items;
};

QueueHandle_t xQueueCreateWithCaps(UBaseType_t length, UBaseType_t item_size, UBaseType_t caps)
{
  struct QueueDefinition *q;
  size_t bytes = length * item_size;

  q = kmm_zalloc(sizeof(*q) + bytes);
  if (!q) return NULL;

  q->storage = (uint8_t *)(q + 1);
  q->item_size = item_size;
  q->length = length;
  nxsem_init(&q->items, 0, 0);
  return q;
}

BaseType_t xQueueSendFromISR(QueueHandle_t q, const void *item, BaseType_t *woken)
{
  irqstate_t flags = enter_critical_section();
  if (q->count >= q->length)
    {
      leave_critical_section(flags);
      return pdFALSE;
    }

  memcpy(&q->storage[q->head * q->item_size], item, q->item_size);
  q->head = (q->head + 1) % q->length;
  q->count++;
  leave_critical_section(flags);

  nxsem_post(&q->items);
  if (woken) *woken = pdTRUE;
  return pdTRUE;
}

BaseType_t xQueueReceive(QueueHandle_t q, void *buf, TickType_t ticks)
{
  int ret;

  if (ticks == portMAX_DELAY)
    ret = nxsem_wait_uninterruptible(&q->items);
  else
    ret = nxsem_tickwait(&q->items, ticks);

  if (ret != OK) return pdFALSE;

  irqstate_t flags = enter_critical_section();
  memcpy(buf, &q->storage[q->tail * q->item_size], q->item_size);
  q->tail = (q->tail + 1) % q->length;
  q->count--;
  leave_critical_section(flags);
  return pdTRUE;
}

void xQueueReset(QueueHandle_t q)
{
  irqstate_t flags = enter_critical_section();
  q->head = 0;
  q->tail = 0;
  q->count = 0;
  leave_critical_section(flags);
  nxsem_reset(&q->items, 0);
}

void vQueueDeleteWithCaps(QueueHandle_t q)
{
  nxsem_destroy(&q->items);
  kmm_free(q);
}
