void esp_os_queue_delete_with_caps(esp_os_queue_handle_t queue)
{
  FAR struct mq_adpt *mq_adpt = (FAR struct mq_adpt *)queue;

  ASSERT(file_mq_close(&mq_adpt->mq) == OK);
  ASSERT(file_mq_unlink(mq_adpt->name) == OK);
  kmm_free(mq_adpt);
}

