   * initialised (matches ESP-IDF's esp_intr_alloc() behaviour).
   */

  if ((flags & ESP_INTR_FLAG_INTRDISABLED) == 0)
    {
      up_enable_irq(irq);
    }

  return ESP_OK;
}

