int esp_os_wait_sem_timeout(FAR esp_os_sem_t *sem, uint32_t timeout_ticks)
{
  int ret;

  esp_os_drain_sem(sem);

  if (timeout_ticks == UINT32_MAX)
    {
      ret = nxsem_wait(sem);
    }
  else
    {
      ret = nxsem_tickwait(sem, timeout_ticks);
    }

  return ret == OK ? 0 : ret;
}
