Semaphore 实现:
```c
xSemaphoreCreateBinaryWithCaps(caps) {
    sem_t *sem = kmm_malloc(sizeof(sem_t));
    nxsem_init(sem, 0, 0);
    return (SemaphoreHandle_t)sem;
}

xSemaphoreGive(sem) {
    return nxsem_post((sem_t*)sem) == OK ? pdTRUE : pdFALSE;
}

xSemaphoreTake(sem, ticks) {
    int ret;
    if (ticks == portMAX_DELAY) {
        do { ret = nxsem_wait_uninterruptible((sem_t*)sem); } while (ret != OK && ret != -EINTR);
    } else {
        ret = nxsem_tickwait((sem_t*)sem, ticks);
    }
    return ret == OK ? pdTRUE : pdFALSE;
}

vSemaphoreDeleteWithCaps(sem) {
    nxsem_destroy((sem_t*)sem);
    kmm_free(sem);
}
```

