267	  ctx->out_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
268	  ctx->out_fmt.fmt.pix.width  = 1024;
269	  ctx->out_fmt.fmt.pix.height = 600;
270	  ctx->out_fmt.fmt.pix.sizeimage = JPEG_OUT_BUF_SIZE(1024, 600);
