275	  ctx->cap_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
276	  ctx->cap_fmt.fmt.pix.width  = 1024;
277	  ctx->cap_fmt.fmt.pix.height = 600;
278	  ctx->cap_fmt.fmt.pix.sizeimage = JPEG_CAP_BUF_SIZE(1024, 600);
279	
280	  ret = codec_register(devpath, codec);
281	  if (ret < 0)
282	    {
283	      kmm_free(codec);
284	      kmm_free(ctx);
285	      return ret;
286	    }
