  jpeg_encoder_process(d->engine, &in_enc, &out_enc, &cfg);
  cap->bytesused = out_enc.jpeg_buf_size;
  codec_capture_put_buf(d->cookie, cap);
  codec_output_put_buf(d->cookie, in);
  return 0;
}
