64	 *
65	 * Description:
66	 *   Wait for a semaphore, blocking up to xBlockTime ticks.
67	 *
68	 ****************************************************************************/
69	
70	BaseType_t xSemaphoreTake(SemaphoreHandle_t xSemaphore,
71	                          TickType_t xBlockTime)
72	{
73	  FAR struct freertos_sem_s *sem = (FAR struct freertos_sem_s *)xSemaphore;
