33	/****************************************************************************
34	 * Private Helpers
35	 ****************************************************************************/
36	
37	/* Effective alignment to request from the NuttX allocator.
38	 *
39	 * ESP-IDF allocates DMA-capable memory through heap_caps_* with an
40	 * internal knowledge of the target cache line size.  The NuttX
41	 * reimplementation just forwards whatever alignment the caller passes to
42	 * kmm_memalign(), which is typically 4 bytes for emac_esp_dma.c.  When the
43	 * caller asks for MALLOC_CAP_DMA (optionally also _INTERNAL/_8BIT), the
44	 * resulting buffer must be cache-line aligned, otherwise esp_cache_msync()
45	 * on ESP32-P4 aborts with ESP_ERR_INVALID_ARG and the assertion in
46	 * esp_eth_mac_esp_dma.c fires.  Bump the alignment up to the L2 cache line
47	 * size for DMA-capable allocations.
48	 */
49	
50	#if defined(CONFIG_CACHE_L2_CACHE_LINE_SIZE)
51	#  define ESP_HEAP_CAPS_DMA_ALIGN CONFIG_CACHE_L2_CACHE_LINE_SIZE
52	#elif defined(CONFIG_CACHE_L1_CACHE_LINE_SIZE)
53	#  define ESP_HEAP_CAPS_DMA_ALIGN CONFIG_CACHE_L1_CACHE_LINE_SIZE
54	#else
55	#  define ESP_HEAP_CAPS_DMA_ALIGN 4
56	#endif
57	
58	static inline size_t esp_heap_caps_effective_alignment(size_t alignment,
59	                                                        uint32_t caps)
60	{
61	  if ((caps & MALLOC_CAP_DMA) != 0 && alignment < ESP_HEAP_CAPS_DMA_ALIGN)
62	    {
63	      return ESP_HEAP_CAPS_DMA_ALIGN;
64	    }
65	
66	  return alignment;
67	}
