75	static bool esp_heap_caps_retention_caps_exact(uint32_t caps)
76	{
77	  return (caps & MALLOC_CAP_RETENTION) != 0 &&
78	         (caps & ~MALLOC_CAP_RETENTION) == 0;
79	}
80	
