111	/****************************************************************************
112	 * Name: heap_caps_malloc
113	 *
114	 * Description:
115	 *   Allocate memory with the given capabilities.  Most requests use
116	 *   kmm_malloc; with CONFIG_ESPRESSIF_RETENTION_HEAP, MALLOC_CAP_RETENTION
117	 *   only uses the retention mm heap.
118	 *
119	 ****************************************************************************/
120	
121	void *heap_caps_malloc(size_t size, uint32_t caps)
122	{
123	  FAR void *ptr;
124	
125	  if (esp_heap_caps_retention_caps_exact(caps))
126	    {
127	      ptr = esp_retentionheap_malloc(size);
128	    }
129	  else
130	    {
131	      ptr = kmm_malloc(size);
132	    }
133	
134	  if (ptr == NULL && alloc_failed_callback)
135	    {
136	      alloc_failed_callback(size, caps, __func__);
137	    }
138	
139	  return ptr;
140	}
