142	/****************************************************************************
143	 * Name: heap_caps_free
144	 *
145	 * Description:
146	 *   Free memory previously allocated via heap_caps_malloc() or
147	 *   heap_caps_realloc().
148	 *
149	 ****************************************************************************/
150	
151	void heap_caps_free(void *ptr)
152	{
153	  if (ptr == NULL)
154	    {
155	      return;
156	    }
157	
158	  if (esp_retentionheap_heapmember(ptr))
159	    {
160	      esp_retentionheap_free(ptr);
161	      return;
162	    }
163	
164	  /* Cross-heap-free instrumentation: in NuttX builds that have a distinct
165	   * user heap (flat + CONFIG_MM_KERNEL_HEAP), heap_caps_calloc/malloc() go
166	   * to the kernel heap via kmm_malloc().  If a pointer allocated with libc
167	   * malloc() (user heap) ends up here, kmm_free() would hit the
168	   * mm_heapmember() assertion in mm_free.c.  Detect this up front and
169	   * route the free to the correct heap, while loudly warning about it so
170	   * we can fix the offending allocation/free pair.
171	   */
172	
173	#ifdef CONFIG_MM_KERNEL_HEAP
174	  if (!kmm_heapmember(ptr))
175	    {
176	      syslog(LOG_ERR,
177	             "heap_caps_free: ptr %p not in kernel heap "
178	             "(cross-heap free, caller=%p); routing to free()\n",
179	             ptr, __builtin_return_address(0));
180	      free(ptr);
181	      return;
182	    }
183	#endif
184	
185	  kmm_free(ptr);
186	}
