188	/****************************************************************************
189	 * Name: heap_caps_realloc
190	 *
191	 * Description:
192	 *   Reallocate memory previously allocated via heap_caps_malloc() or
193	 *   heap_caps_realloc().
194	 *
195	 ****************************************************************************/
196	
197	void *heap_caps_realloc(void *ptr, size_t size, uint32_t caps)
198	{
199	  FAR void *new_ptr;
200	
201	  if (ptr == NULL)
202	    {
203	      return heap_caps_malloc(size, caps);
204	    }
205	
206	  if (esp_retentionheap_heapmember(ptr))
207	    {
208	      if (size == 0)
209	        {
210	          esp_retentionheap_free(ptr);
211	          return NULL;
212	        }
213	
214	      new_ptr = esp_retentionheap_realloc(ptr, size);
215	    }
216	  else
217	    {
218	      new_ptr = kmm_realloc(ptr, size);
219	    }
220	
221	  if (new_ptr == NULL && size > 0 && alloc_failed_callback)
222	    {
223	      alloc_failed_callback(size, caps, __func__);
224	    }
225	
226	  return new_ptr;
227	}
