void esp_teardown_irq(int source, int cpuint)
{
  esp_err_t ret;
  int cpu = this_cpu();
  int irq = ESP_SOURCE2IRQ(source);
  intr_handle_t intr_handle = esp_get_handle(cpu, irq);

  UNUSED(cpuint);

  if (intr_handle == IRQ_UNMAPPED)
    {
      irqwarn("No handle found for source %d\n", source);
