785	 *
786	 * Description:
787	 *   Find an IRQ associated with a given CPU interrupt by searching through
788	 *   g_handle_map. For shared interrupts, multiple IRQs may map to the same
789	 *   CPU interrupt - this function returns the first one found.
790	 *
791	 * Input Parameters:
792	 *   cpuint - The CPU interrupt number
793	 *   cpu    - The CPU core
794	 *
795	 * Returned Value:
796	 *   The IRQ number, or -1 if not found.
797	 *
798	 ****************************************************************************/
799	
800	IRAM_ATTR int esp_cpuint_to_irq(int cpuint, int cpu)
801	{
802	  int irq;
803	  intr_handle_t handle;
804	
805	  for (irq = 0; irq < NR_IRQS; irq++)
806	    {
807	      handle = g_handle_map[cpu][irq];
808	      if (handle != IRQ_UNMAPPED && handle != NULL)
809	        {
810	          if (esp_intr_get_intno(handle) == cpuint &&
811	              esp_intr_get_cpu(handle) == cpu)
812	            {
813	              return irq;
814	            }
815	        }
816	    }
817	
818	  return -1;
819	}
