      return ESP_OK;
    }

  if (errno_value == -EINVAL)
    {
      return ESP_ERR_INVALID_ARG;
    }

  if (errno_value == -ENOMEM)
    {
      return ESP_ERR_NO_MEM;
    }

  if (errno_value == -EALREADY || errno_value == -EBUSY)
    {
      return ESP_ERR_INVALID_STATE;
    }

  return ESP_FAIL;
}

