/****************************************************************************
 * apps/examples/jpegenc/jpegenc_main.c
 *
 * Encode one RGB565 frame to JPEG using the ESP32-P4 hardware JPEG encoder
 * (/dev/video1, V4L2 M2M).
 *
 * Input:  /data/capture.rgb565  (1024x600 RGB565, from camcap)
 * Output: /data/capture.jpg
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <malloc.h>
#include <poll.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/videoio.h>

#define M2M_DEV     "/dev/video1"
#define IN_FILE     "/tmp/capture.rgb565"
#define OUT_FILE    "/tmp/capture.jpg"
#define W           1024
#define H           600

/* RGB565 input frame size (2 bytes/pixel) */
#define OUT_SIZE    (W * H * 2)
/* JPEG output buffer: driver uses W*H for capture sizeimage, but allow slack */
#define CAP_SIZE    (W * H * 2)

static int xioctl(int fd, int req, void *arg)
{
  int r;
  do { r = ioctl(fd, req, arg); } while (r == -1 && errno == EINTR);
  return r;
}

int main(int argc, char *argv[])
{
  int fd = -1, infd = -1, outfd = -1;
  int ret = EXIT_FAILURE;
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  void *inbuf = NULL;
  void *capbuf = NULL;
  enum v4l2_buf_type out_type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
  enum v4l2_buf_type cap_type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  size_t n;

  printf("jpegenc: %dx%d RGB565 -> JPEG via %s\n", W, H, M2M_DEV);
  fflush(stdout);

  /* Load the RGB565 input frame */

  infd = open(IN_FILE, O_RDONLY, 0);
  if (infd < 0)
    { printf("ERROR: open %s: %d\n", IN_FILE, errno); goto out; }

  inbuf = memalign(64, OUT_SIZE);
  if (!inbuf)
    { printf("ERROR: memalign input\n"); goto out; }

  n = read(infd, inbuf, OUT_SIZE);
  if (n < 0)
    { printf("ERROR: read input got %ld bytes\n", (long)n); goto out; }
  printf("  loaded %ld bytes from %s\n", (long)n, IN_FILE);
  fflush(stdout);

  /* Open M2M device */

  fd = open(M2M_DEV, O_RDWR, 0);
  if (fd < 0)
    { printf("ERROR: open %s: %d\n", M2M_DEV, errno); goto out; }

  /* Set OUTPUT queue format: RGB565 */

  memset(&fmt, 0, sizeof(fmt));
  fmt.type                = out_type;
  fmt.fmt.pix.width       = W;
  fmt.fmt.pix.height      = H;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
  if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
    { printf("ERROR: OUTPUT S_FMT: %d\n", errno); goto out; }
  printf("  OUTPUT fmt: %ux%u sizeimage=%u\n",
         (unsigned int)fmt.fmt.pix.width, (unsigned int)fmt.fmt.pix.height,
         (unsigned int)fmt.fmt.pix.sizeimage);
  fflush(stdout);

  /* Set CAPTURE queue format: JPEG */

  memset(&fmt, 0, sizeof(fmt));
  fmt.type                = cap_type;
  fmt.fmt.pix.width       = W;
  fmt.fmt.pix.height      = H;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
  if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
    { printf("ERROR: CAPTURE S_FMT: %d\n", errno); goto out; }
  printf("  CAPTURE fmt: %ux%u sizeimage=%u\n",
         (unsigned int)fmt.fmt.pix.width, (unsigned int)fmt.fmt.pix.height,
         (unsigned int)fmt.fmt.pix.sizeimage);
  fflush(stdout);

  /* Request buffers on both queues (USERPTR) */

  memset(&req, 0, sizeof(req));
  req.type   = out_type;
  req.memory = V4L2_MEMORY_USERPTR;
  req.count  = 2;
  if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0)
    { printf("ERROR: OUTPUT REQBUFS: %d\n", errno); goto out; }

  memset(&req, 0, sizeof(req));
  req.type   = cap_type;
  req.memory = V4L2_MEMORY_USERPTR;
  req.count  = 2;
  if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0)
    { printf("ERROR: CAPTURE REQBUFS: %d\n", errno); goto out; }

  /* Allocate capture buffer and queue it on the CAPTURE queue */

  capbuf = memalign(64, CAP_SIZE);
  if (!capbuf)
    { printf("ERROR: memalign capture\n"); goto out; }

  memset(&buf, 0, sizeof(buf));
  buf.type      = cap_type;
  buf.memory    = V4L2_MEMORY_USERPTR;
  buf.index     = 0;
  buf.m.userptr = (unsigned long)capbuf;
  buf.length    = CAP_SIZE;
  if (xioctl(fd, VIDIOC_QBUF, &buf) < 0)
    { printf("ERROR: CAPTURE QBUF: %d\n", errno); goto out; }

  /* Queue input frame on OUTPUT queue */

  memset(&buf, 0, sizeof(buf));
  buf.type      = out_type;
  buf.memory    = V4L2_MEMORY_USERPTR;
  buf.index     = 0;
  buf.m.userptr = (unsigned long)inbuf;
  buf.length    = OUT_SIZE;
  buf.bytesused = OUT_SIZE;
  if (xioctl(fd, VIDIOC_QBUF, &buf) < 0)
    { printf("ERROR: OUTPUT QBUF: %d\n", errno); goto out; }

  /* Start both queues */

  if (xioctl(fd, VIDIOC_STREAMON, &out_type) < 0)
    { printf("ERROR: OUTPUT STREAMON: %d\n", errno); goto out; }
  if (xioctl(fd, VIDIOC_STREAMON, &cap_type) < 0)
    { printf("ERROR: CAPTURE STREAMON: %d\n", errno); goto out; }
  printf("  streaming...\n");
  fflush(stdout);

  /* Wait for the encoded frame to be ready (DQBUF returns EAGAIN until then) */

  {
    struct pollfd pfd;
    int pret;

    pfd.fd     = fd;
    pfd.events = POLLIN;
    pfd.revents = 0;
    for (int tries = 0; tries < 50; tries++)
      {
        pret = poll(&pfd, 1, 100);
        if (pret < 0)
          { printf("ERROR: poll: %d\n", errno); goto out; }
        if (pret > 0 && (pfd.revents & POLLIN))
          {
            break;
          }
      }

    if (pret <= 0 || !(pfd.revents & POLLIN))
      {
        printf("ERROR: timeout waiting for encoded frame\n");
        goto out;
      }
  }

  /* Dequeue encoded JPEG */

  memset(&buf, 0, sizeof(buf));
  buf.type   = cap_type;
  buf.memory = V4L2_MEMORY_USERPTR;
  if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0)
    { printf("ERROR: CAPTURE DQBUF: %d\n", errno); goto out; }
  printf("  encoded frame %u: %u bytes\n",
         (unsigned int)buf.index, (unsigned int)buf.bytesused);
  fflush(stdout);

  /* Write JPEG to file */

  outfd = open(OUT_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (outfd < 0)
    { printf("ERROR: open %s: %d\n", OUT_FILE, errno); goto out; }

  n = write(outfd, capbuf, buf.bytesused);
  if (n < 0)
    { printf("ERROR: write: %d\n", errno); goto out; }
  printf("  wrote %ld bytes to %s\n", (long)n, OUT_FILE);
  fflush(stdout);

  /* Cleanup */

  xioctl(fd, VIDIOC_QBUF, &buf);
  xioctl(fd, VIDIOC_STREAMOFF, &cap_type);
  xioctl(fd, VIDIOC_STREAMOFF, &out_type);
  ret = EXIT_SUCCESS;

out:
  if (outfd >= 0) close(outfd);
  if (infd >= 0) close(infd);
  if (fd >= 0) close(fd);
  free(inbuf);
  free(capbuf);
  return ret;
}

/****************************************************************************
 * Inline Functions
 ****************************************************************************/

#ifdef CONFIG_ARCH_RV_HAVE_CLIC

/****************************************************************************
 * Name: up_irq_save
 *
 * Description:
 *   Disable interrupts by setting interrupt threshold to maximum and return
 *   the previous threshold value
 *
 ****************************************************************************/

noinstrument_function static inline_function irqstate_t up_irq_save(void)
{
  /* Read current interrupt threshold and set to maximum to mask all */

  return SWAP_CSR(CSR_INTTHRESH, RISCV_MAX_INTTHRESH);
}

/****************************************************************************
 * Name: up_irq_restore
 *
 * Description:
 *   Restore the value of the interrupt threshold register
 *
 ****************************************************************************/

noinstrument_function static inline_function
void up_irq_restore(irqstate_t flags)
{
  /* Restore the interrupt threshold value */

  WRITE_CSR(CSR_INTTHRESH, flags);
}

#else

/****************************************************************************
 * Name: up_irq_save
 *
 * Description:
 *   Disable interrupts and return the previous value of the mstatus register
 *
 ****************************************************************************/

noinstrument_function static inline_function irqstate_t up_irq_save(void)
{
  irqstate_t flags;

  /* Read mstatus & clear machine interrupt enable (MIE) in mstatus */

  __asm__ __volatile__
    (
      "csrrc %0, " __XSTR(CSR_STATUS) ", %1\n"
      : "=r" (flags)
      : "r"(STATUS_IE)
      : "memory"
    );

  /* Return the previous mstatus value so that it can be restored with
   * up_irq_restore().
   */

  return flags;
}

/****************************************************************************
 * Name: up_irq_restore
 *
 * Description:
 *   Restore the value of the mstatus register
 *
 ****************************************************************************/

noinstrument_function static inline_function
void up_irq_restore(irqstate_t flags)
{
  __asm__ __volatile__
    (
      "csrw " __XSTR(CSR_STATUS) ", %0\n"
      : /* no output */
      : "r" (flags)
      : "memory"
    );
}

#endif /* CONFIG_ARCH_RV_HAVE_CLIC */

/****************************************************************************
 * Name: up_set_interrupt_context
 *
 * Description:
 *   Set the interrupt handler context.
 *
 ****************************************************************************/

noinstrument_function
static inline_function void up_set_interrupt_context(bool flag)
{
  g_interrupt_context = flag;
}

