import serial, time
LOG = open('/tmp/jpeg_diag5.log', 'ab', buffering=0)
ser = serial.Serial('/dev/ttyACM0', 115200, timeout=0.2)
time.sleep(1.0)
def pump(dur, note):
    LOG.write(b'[[%s start]]\n' % note.encode())
    end = time.time() + dur; idle = 0
    while time.time() < end:
        d = ser.read(2048)
        if d: LOG.write(d); idle = 0
        else:
            idle += 1
            if idle > 120:
                LOG.write(b'[[%s silent-stop]]\n' % note.encode()); return
            time.sleep(0.005)
    LOG.write(b'[[%s end]]\n' % note.encode())
def send(cmd, dur, note):
    ser.write((cmd + '\n').encode()); pump(dur, note)
def wait_idle(tmo=15):
    last = time.time(); end = time.time() + tmo
    while time.time() < end:
        d = ser.read(1024)
        if d: LOG.write(d); last = time.time()
        else:
            if time.time() - last > 0.6: return
            time.sleep(0.005)
wait_idle()
send('dd if=/dev/zero of=/tmp/capture.rgb565 bs=1024 count=1200', 8, 'dd')
send('jpegenc', 60, 'jpegenc')
LOG.write(b'[[ALLDONE]]\n')
ser.close(); LOG.close(); print("DONE")

