void esp_usbserial_write(char ch)
{
  /* Non-blocking: if the USB-Serial-JTAG TX FIFO is full, drop the byte
   * instead of spinning on serial_in_ep_data_free.  A blocking wait here
   * deadlocks the caller when the console TX interrupt (SERIAL_IN_EMPTY)
   * is masked for polled debugging output: nothing drains the FIFO. */

  if (!esp_txready(&g_uart_usbserial))
    {
      return;
    }

  esp_send(&g_uart_usbserial, ch);
}

/****************************************************************************
 * Name: dbg_putc
 *
 * Description:
 *   Polled debug marker with a bounded wait.  If the USB-Serial-JTAG TX
 *   FIFO is momentarily full, poll esp_txready for a short bounded time
 *   (so a live console ISR has a chance to drain it) and then give up.
 *   Unlike esp_usbserial_write (which drops immediately) this recovers
 *   markers lost to transient full-FIFO states; unlike a plain blocking
 *   wait it can never deadlock when nothing drains the FIFO.
 *
 ****************************************************************************/

void dbg_putc(int ch)
{
  volatile int tries = 0;

  while (!esp_txready(&g_uart_usbserial))
    {
      if (++tries > 200000)
        {
          return;               /* FIFO never drained: give up, no spin */
        }
    }

  esp_send(&g_uart_usbserial, ch);
}

