159	  if (xioctl(fd, VIDIOC_STREAMON, &cap_type) < 0)
160	    { printf("ERROR: CAPTURE STREAMON: %d\n", errno); goto out; }
161	  printf("  streaming...\n");
162	  fflush(stdout);
163	
164	  /* Wait for the encoded frame to be ready (DQBUF returns EAGAIN until then) */
165	
166	  {
167	    struct pollfd pfd;
168	    int pret;
169	
170	    pfd.fd     = fd;
171	    pfd.events = POLLIN;
172	    pfd.revents = 0;
173	    for (int tries = 0; tries < 50; tries++)
174	      {
175	        pret = poll(&pfd, 1, 100);
176	        if (pret < 0)
177	          { printf("ERROR: poll: %d\n", errno); goto out; }
178	        if (pret > 0 && (pfd.revents & POLLIN))
179	          {
180	            break;
181	          }
182	      }
183	
184	    if (pret <= 0 || !(pfd.revents & POLLIN))
