196	  if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0)
197	    { printf("ERROR: CAPTURE DQBUF: %d\n", errno); goto out; }
198	  printf("  encoded frame %u: %u bytes\n",
199	         (unsigned int)buf.index, (unsigned int)buf.bytesused);
200	  fflush(stdout);
201	
202	  /* Write JPEG to file */
203	
204	  outfd = open(OUT_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
205	  if (outfd < 0)
206	    { printf("ERROR: open %s: %d\n", OUT_FILE, errno); goto out; }
207	
208	  n = write(outfd, capbuf, buf.bytesused);
209	  if (n < 0)
210	    { printf("ERROR: write: %d\n", errno); goto out; }
211	  printf("  wrote %ld bytes to %s\n", (long)n, OUT_FILE);
212	  fflush(stdout);
213	
214	  /* Cleanup */
215	
216	  xioctl(fd, VIDIOC_QBUF, &buf);
217	  xioctl(fd, VIDIOC_STREAMOFF, &cap_type);
218	  xioctl(fd, VIDIOC_STREAMOFF, &out_type);
219	  ret = EXIT_SUCCESS;
220	
221	out:
222	  if (outfd >= 0) close(outfd);
223	  if (infd >= 0) close(infd);
224	  if (fd >= 0) close(fd);
225	  free(inbuf);
226	  free(capbuf);
227	  return ret;
228	}
