505	/****************************************************************************
506	 * Name: dbg_putc
507	 *
508	 * Description:
509	 *   Polled debug marker with a bounded wait and proper USB transaction
510	 *   handling.  Works with interrupts masked.  Never blocks forever.
511	 *
512	 *   The USB-Serial-JTAG TX FIFO auto-flushes a full 64-byte packet but
513	 *   without a "transaction complete" signal, so the host holds those 64
514	 *   bytes as an incomplete USB transaction unless we follow up with a
515	 *   zero-length packet once the FIFO frees.  We therefore wait for FIFO
516	 *   room, write one byte, flush, and then -- if the FIFO becomes full and
517	 *   frees again -- flush a second time to emit the ZLP (see ESP-IDF
518	 *   usb_serial_jtag_wait_tx_done_no_driver).  Each wait is bounded, so a
519	 *   host that stopped pulling costs at most one marker, never a hang.
520	 *
521	 ****************************************************************************/
522	
523	void dbg_putc(int ch)
524	{
525	  volatile int tries = 0;
526	  uint8_t b = (uint8_t)ch;
527	
528	  /* Record the character in the RAM marker before attempting TX. */
529	
530	  *DBG_MARK_ADDR = b;
531	  g_dbg_mark = b;
532	
533	  /* Wait for FIFO room so the byte actually lands. */
534	
535	  while (!esp_txready(&g_uart_usbserial))
536	    {
537	      if (++tries > 300000)
538	        {
539	          return;               /* host not pulling: give up, no spin */
540	        }
541	    }
542	
543	  /* Write the byte and mark the transaction done. */
544	
545	  usb_serial_jtag_ll_write_txfifo(&b, 1);
546	  usb_serial_jtag_ll_txfifo_flush();
547	
548	  /* If the byte filled the FIFO to 64, the HW auto-flushes it as a
549	   * possibly-incomplete transaction.  Wait for the FIFO to free, then
550	   * send a zero-length packet so the host delivers the last 64 bytes. */
551	
552	  tries = 0;
553	  while (!esp_txready(&g_uart_usbserial))
554	    {
555	      if (++tries > 300000)
556	        {
557	          return;
558	        }
559	    }
560	
561	  usb_serial_jtag_ll_txfifo_flush();        /* zero-length packet */
562	}
563	
564	/****************************************************************************
565	 * Name: dbg_mark_char
566	 *
567	 * Description:
568	 *   Record a character into the RAM marker and attempt a non-blocking TX of
569	 *   it (same behavior as the bare up_putc markers).  Used inside spin-lock
570	 *   critical sections where a bounded polled wait is undesirable; the RAM
571	 *   marker write is what matters for post-hang diagnosis.
572	 *
573	 ****************************************************************************/
574	
575	void dbg_mark_char(int ch)
576	{
577	  *DBG_MARK_ADDR = (uint8_t)ch;
578	  g_dbg_mark = (uint8_t)ch;
579	  esp_usbserial_write((char)ch);
580	}
