567	  extern void up_putc(int ch);
568	  static const char hex[] = "0123456789ABCDEF";
569	  if (g_arm_dbg)
570	    {
571	      g_arm_dbg = 0;
572	      up_putc('T'); up_putc(hex[(mcause >> 28) & 0xF]); up_putc(hex[(mcause >> 24) & 0xF]);
573	      up_putc(hex[(mcause >> 20) & 0xF]); up_putc(hex[(mcause >> 16) & 0xF]);
574	      up_putc(hex[(mcause >> 12) & 0xF]); up_putc(hex[(mcause >> 8) & 0xF]);
575	      up_putc(hex[(mcause >> 4) & 0xF]);  up_putc(hex[mcause & 0xF]); up_putc(' ');
576	    }
