804	/****************************************************************************
805	 * Name: esp_cpuint_to_irq
806	 *
807	 * Description:
808	 *   Find an IRQ associated with a given CPU interrupt by searching through
809	 *   g_handle_map. For shared interrupts, multiple IRQs may map to the same
810	 *   CPU interrupt - this function returns the first one found.
811	 *
812	 * Input Parameters:
813	 *   cpuint - The CPU interrupt number
814	 *   cpu    - The CPU core
815	 *
816	 * Returned Value:
817	 *   The IRQ number, or -1 if not found.
818	 *
819	 ****************************************************************************/
820	
821	IRAM_ATTR int esp_cpuint_to_irq(int cpuint, int cpu)
822	{
823	  int irq;
824	  intr_handle_t handle;
825	
826	  for (irq = 0; irq < NR_IRQS; irq++)
827	    {
828	      handle = g_handle_map[cpu][irq];
829	      if (handle != IRQ_UNMAPPED && handle != NULL)
830	        {
831	          if (esp_intr_get_intno(handle) == cpuint &&
832	              esp_intr_get_cpu(handle) == cpu)
833	            {
834	              return irq;
835	            }
836	        }
837	    }
838	
839	  return -1;
840	}
