FORCE_INLINE_ATTR uint32_t rv_utils_get_interrupt_threshold(void)
{
#if INTTHRESH_STANDARD
    uint32_t threshold;
    if (IS_PRV_M_MODE()) {
        threshold = RV_READ_CSR(MINTTHRESH_CSR);
