      is_edge = esprv_int_get_type(cpuint) != INTR_TYPE_LEVEL;
      if (is_edge)
        {
          /* Clear edge interrupts. */

          esp_cpu_intr_edge_ack(cpuint);
        }
    }
  else
    {
      /* It's exception */

      irq = mcause &
            (VECTORS_MCAUSE_INTBIT_MASK | VECTORS_MCAUSE_REASON_MASK);
    }

  regs = riscv_doirq(irq, regs);

  return regs;
}

