static void ESP_INTR_IRAM_ATTR shared_intr_isr(void *arg)
{
    vector_desc_t *vd = (vector_desc_t*)arg;
    shared_vector_desc_t *sh_vec = vd->shared_vec_info;
    (*((volatile uint32_t *)0x5010ffd8))++;  /* shared_intr_isr run counter */
    *((volatile uint32_t *)0x5010ffdc) = (uint32_t)vd->intno;  /* which CPU int */
    *((volatile uint32_t *)0x5010ffbc) = (uint32_t)vd->flags;  /* vector flags */
    if (sh_vec) {
        *((volatile uint32_t *)0x5010ffc8) = (uint32_t)sh_vec->source;
        *((volatile uint32_t *)0x5010ffc4) = sh_vec->statusreg ?
            (uint32_t)*sh_vec->statusreg : 0xffffffffu;
        *((volatile uint32_t *)0x5010ffc0) = (uint32_t)sh_vec->statusmask;
    }
    dbg_putc('k');              /* shared_intr_isr entered (was 'K': change the
                                 * output char so a flood of 'k' identifies this
                                 * ISR as the source on the lossy console) */
    static int s_sh_once = 0;
    if (!s_sh_once) {
        s_sh_once = 1;
        up_putc('S'); dbgm_hx((uint32_t)vd->intno); up_putc('f'); dbgm_hx((uint32_t)vd->flags);
        {
            shared_vector_desc_t *sv = vd->shared_vec_info;
            int n = 0;
            while (sv && n < 8) {
                up_putc('[');
                dbgm_hx((uint32_t)sv->source);          /* source id */
                up_putc(':');
                dbgm_hx(sv->statusreg ? (uint32_t)*sv->statusreg : 0xffffffffu);  /* reg value */
                up_putc(':');
                dbgm_hx((uint32_t)sv->statusmask);      /* mask */
                up_putc(']');
                sv = sv->next; n++;
            }
        }
        {
            /* reverse scan int_map: which sources route to this intno.
             * Latch the first two found and the count into warm-reset markers
             * (console is lossy during the storm). */
            volatile uint32_t *map = (volatile uint32_t *)0x500D6000;  /* INTR_CORE0_BASE */
            int s, cnt = 0;
            uint32_t f1 = 0xffffffff, f2 = 0xffffffff;
            /* The interrupt mux routes to the CLIC interrupt number, which is
             * the logical cpuint + RV_EXTERNAL_INT_OFFSET (16).  vd->intno is
             * the logical number, so scan for the real CLIC int (intno+16). */
            for (s = 0; s < 133; s++) {
                if ((map[s] & 0x3F) == (uint32_t)(vd->intno + 16)) {
                    if (f1 == 0xffffffff) f1 = (uint32_t)s;
                    else if (f2 == 0xffffffff) f2 = (uint32_t)s;
                    cnt++;
                }
            }
            *((volatile uint32_t *)0x5010ff90) = f1;
            *((volatile uint32_t *)0x5010ff94) = f2;
            *((volatile uint32_t *)0x5010ff98) = (uint32_t)cnt;
        }
        {
            /* raw int_map values for key sources + CLIC int5 register */
            volatile uint32_t *map = (volatile uint32_t *)0x500D6000;
            volatile uint32_t *clic = (volatile uint32_t *)0x20801000;
            *((volatile uint32_t *)0x5010ff80) = map[95] & 0x3F;   /* JPEG route */
            *((volatile uint32_t *)0x5010ff84) = map[104] & 0x3F;  /* DMA2D_IN_CH0 route */
            *((volatile uint32_t *)0x5010ff88) = map[5] & 0x3F;    /* source-5 route */
            *((volatile uint32_t *)0x5010ff8c) = clic[5] & 0xFF;   /* CLIC int5 pending/ena */
            /* CLICINTCTL full 32-bit for the real CLIC ints (intno+16):
             * bit8=IE, bit0=IP, [31:24]=prio. int21=jpeg route; 18/19/20 =
             * boot's exclusive allocs (cpuint 2/3/4). */
            *((volatile uint32_t *)0x5010ff70) = clic[21];  /* CLIC int21 (jpeg) */
            *((volatile uint32_t *)0x5010ff74) = clic[18];  /* CLIC int18 (boot cpuint2) */
            *((volatile uint32_t *)0x5010ff78) = clic[19];  /* CLIC int19 (boot cpuint3) */
            *((volatile uint32_t *)0x5010ff7c) = clic[20];  /* CLIC int20 (boot cpuint4) */
        }
        {
            /* jpeg peripheral int regs (JPEG_BASE 0x50086000) */
            volatile uint32_t *jp = (volatile uint32_t *)0x50086000;
            up_putc('A'); dbgm_wx(jp[0x38 / 4]);  /* int_raw */
            up_putc('B'); dbgm_wx(jp[0x3c / 4]);  /* int_ena */
            up_putc('C'); dbgm_wx(jp[0x40 / 4]);  /* int_st */
        }
        {
            /* CLIC int5 register (pending/enable byte) */
            volatile uint32_t *clic = (volatile uint32_t *)0x20801000;
            up_putc('D'); dbgm_hx(clic[5] & 0xFF);
        }
    }
    esp_os_enter_critical_isr(&spinlock);
    while(sh_vec) {
        if (!sh_vec->disabled) {
            if ((sh_vec->statusreg == NULL) || (*sh_vec->statusreg & sh_vec->statusmask)) {
                *((volatile uint32_t *)0x5010ffcc) = (uint32_t)sh_vec->source;  /* source */
