     * console).  Updated every call so the M dump after a hard reset shows the
     * state at the END of the storm.  0x5010ff00..0x5010ff28. */
    {
        volatile uint32_t *clic = (volatile uint32_t *)0x20801000;
        volatile uint32_t *jp   = (volatile uint32_t *)0x50086000;
        volatile uint32_t *m = (volatile uint32_t *)0x5010ff00;
        uint32_t mc;
        asm volatile("csrr %0, 0x342" : "=r"(mc));   /* mcause */
        m[0x00/4] = mc;
        m[0x04/4] = clic[21];                        /* CLIC int21 (jpeg route): IE=bit8,IP=bit0,TRIG=17:18 */
        m[0x08/4] = clic[5];                         /* CLIC int5 */
        m[0x0c/4] = *((volatile uint32_t *)0x20800000); /* CLICCFG: validate base (NLBITS=bit4:1) */
        m[0x10/4] = *((volatile uint32_t *)0x20800004); /* CLICINFO */
        uint32_t st;
        asm volatile("csrr %0, 0x300" : "=r"(st));   /* mstatus */
        m[0x14/4] = st;
        m[0x18/4] = jp[0x38/4];  /* jpeg int_raw */
        m[0x1c/4] = jp[0x3c/4];  /* jpeg int_ena */
        m[0x20/4] = jp[0x40/4];  /* jpeg int_st */
        /* source that actually matched the statusmask this call, else none */
        uint32_t matched = 0xffffffffu;
        shared_vector_desc_t *s2 = vd->shared_vec_info;
