         * never service the interrupt -> level-triggered storm. */
        if ((RISCV_IRQ_BIT & mcause) != 0)
          {
            uint8_t cpuint = (uint8_t)((mcause & VECTORS_MCAUSE_REASON_MASK) -
                                       RV_EXTERNAL_INT_OFFSET);
            *irq_lc = (uint32_t)esp_cpuint_to_irq(cpuint, this_cpu());
          }
        else
          {
            *irq_lc = 0xffffffffu;
          }
      }
  }

  /* Last-16-trap mcause ring at 0x5010fe00..0x5010fe3c, head index at
   * 0x5010fe40.  Survives warm reset; the M dump prints it so we can see
   * whether the storm is one interrupt repeating or a mix of traps. */
  {
    volatile uint32_t *ring = (volatile uint32_t *)0x5010fe00;
    volatile uint32_t *head = (volatile uint32_t *)0x5010fe40;
    uint32_t h = *head;
    ring[(h & 0xF)] = (uint32_t)mcause;
    *head = h + 1;
  }

  /* One-shot probe: armed right before the JPEG up_irq_restore re-enables
   * MIE.  Prints the first dispatched interrupt/exception mcause so we can
   * tell an ISR storm / trap apart from a stuck main flow. */
  extern volatile int g_arm_dbg;
  extern void up_putc(int ch);
  static const char hex[] = "0123456789ABCDEF";
  if (g_arm_dbg)
    {
      g_arm_dbg = 0;
      up_putc('T'); up_putc(hex[(mcause >> 28) & 0xF]); up_putc(hex[(mcause >> 24) & 0xF]);
      up_putc(hex[(mcause >> 20) & 0xF]); up_putc(hex[(mcause >> 16) & 0xF]);
      up_putc(hex[(mcause >> 12) & 0xF]); up_putc(hex[(mcause >> 8) & 0xF]);
      up_putc(hex[(mcause >> 4) & 0xF]);  up_putc(hex[mcause & 0xF]); up_putc(' ');
    }

  int irq;
  bool is_irq = (RISCV_IRQ_BIT & mcause) != 0;
  bool is_edge = false;
  int cpu = this_cpu();

  if (is_irq)
    {
      uint8_t cpuint = (mcause & VECTORS_MCAUSE_REASON_MASK) -
                       RV_EXTERNAL_INT_OFFSET;

      DEBUGASSERT(cpuint >= 0 && cpuint < ESP_NCPUINTS);

      irq = esp_cpuint_to_irq(cpuint, cpu);

      if (irq < 0)
        {
          /* No handle in NuttX's g_handle_map.  Interrupts allocated
           * through ESP-HAL's esp_intr_alloc_* (jpeg, dma2d) register
           * their handler in the ESP-HAL table (s_intr_handlers,
           * riscv/interrupt.c) instead of g_handle_map.  Call that
           * handler directly -- its ISR clears the level source, so
           * skipping it would leave the line asserted forever and
           * re-trigger this dispatch (level-triggered storm).
           */

          intr_handler_t hal_handler = intr_handler_get(cpuint);
          if (hal_handler != NULL)
            {
              (*hal_handler)(intr_handler_get_arg(cpuint));
              return regs;
            }

          irqwarn("No IRQ found for cpuint=%d cpu=%d\n", cpuint, cpu);
          return regs;
        }

#ifdef CONFIG_ESPRESSIF_IRAM_ISR_DEBUG
      /* Check if non-IRAM interrupts are disabled */

      if (esp_intr_noniram_is_disabled(cpu))
        {
          /* Sum-up the IRAM-enabled counter associated with the IRQ */

          esp_irq_iram_interrupt_record(irq, this_cpu());
        }
#endif

      is_edge = esprv_int_get_type(cpuint) != INTR_TYPE_LEVEL;
      if (is_edge)
        {
          /* Clear edge interrupts. */

          esp_cpu_intr_edge_ack(cpuint);
        }
    }
  else
    {
      /* It's exception */

      irq = mcause &
            (VECTORS_MCAUSE_INTBIT_MASK | VECTORS_MCAUSE_REASON_MASK);
    }

  regs = riscv_doirq(irq, regs);

  return regs;
}

