232	static int uart_putxmitchar(FAR uart_dev_t *dev, int ch, bool oktoblock)
233	{
234	  irqstate_t flags;
235	  int nexthead;
236	  int ret;
237	
238	  /* Loop until we are able to add the character to the TX buffer. */
239	
240	  for (; ; )
241	    {
242	      /* Increment to see what the next head pointer will be.
243	       * We need to use the "next" head pointer to determine when the
244	       * circular buffer would overrun
245	       */
246	
247	      nexthead = dev->xmit.head + 1;
248	      if (nexthead >= dev->xmit.size)
249	        {
250	          nexthead = 0;
251	        }
252	
253	      /* Check if the TX buffer is full */
254	
255	      if (nexthead != dev->xmit.tail)
256	        {
257	          /* No.. not full.  Add the character to the TX buffer and return. */
258	
259	          dev->xmit.buffer[dev->xmit.head] = ch;
260	          dev->xmit.head = nexthead;
261	          break;
262	        }
263	
264	      /* The TX buffer is full.  Should be block, waiting for the hardware
265	       * to remove some data from the TX buffer?
266	       */
267	
268	      else if (oktoblock)
269	        {
270	          /* The following steps must be atomic with respect to serial
271	           * interrupt handling.
272	           */
273	
274	          flags = uart_spinlock(dev, true);
275	
276	          /* Check again...  In certain race conditions an interrupt may
277	           * have occurred between the test at the top of the loop and
278	           * entering the critical section and the TX buffer may no longer
279	           * be full.
280	           *
281	           * NOTE: On certain devices, such as USB CDC/ACM, the entire TX
282	           * buffer may have been emptied in this race condition.  In that
283	           * case, the logic would hang below waiting for space in the TX
284	           * buffer without this test.
285	           */
286	
287	          if (nexthead != dev->xmit.tail)
288	            {
289	              ret = OK;
290	            }
291	
292	#ifdef CONFIG_SERIAL_REMOVABLE
293	          /* Check if the removable device is no longer connected while we
294	           * have interrupts off.  We do not want the transition to occur
295	           * as a race condition before we begin the wait.
296	           */
297	
298	          else if (dev->disconnected)
299	            {
300	              ret = -ENOTCONN;
301	            }
302	#endif
303	          else
304	            {
305	              /* Wait for some characters to be sent from the buffer with
306	               * the TX interrupt enabled.  When the TX interrupt is enabled,
307	               * uart_xmitchars() should execute and remove some of the data
308	               * from the TX buffer.
309	               *
310	               * NOTE that interrupts will be re-enabled while we wait for
311	               * the semaphore.
312	               */
313	
314	#ifdef CONFIG_SERIAL_TXDMA
315	              uart_dmatxavail(dev);
316	#endif
317	              uart_enabletxint(dev);
318	              uart_spinunlock(dev, true, flags);
319	              ret = nxsem_wait(&dev->xmitsem);
320	              flags = uart_spinlock(dev, true);
321	              uart_disabletxint(dev);
322	            }
323	
324	          uart_spinunlock(dev, true, flags);
325	
326	#ifdef CONFIG_SERIAL_REMOVABLE
327	          /* Check if the removable device was disconnected while we were
328	           * waiting.
329	           */
330	
331	          if (dev->disconnected)
332	            {
333	              return -ENOTCONN;
334	            }
335	#endif
336	
337	          /* Check if we were awakened by signal. */
338	
339	          if (ret < 0)
340	            {
341	              /* A signal received while waiting for the xmit buffer to
342	               * become non-full will abort the transfer.
343	               */
344	
345	              return -EINTR;
346	            }
347	        }
348	
349	      /* The caller has request that we not block for data.  So return the
350	       * EAGAIN error to signal this situation.
351	       */
352	
353	      else
354	        {
355	          return -EAGAIN;
356	        }
357	    }
358	
359	  /* We won't get here.  Some compilers may complain that this code is
360	   * unreachable.
361	   */

1367	static ssize_t uart_write(FAR struct file *filep, FAR const char *buffer,
1368	                          size_t buflen)
1369	{
1370	  FAR struct inode *inode    = filep->f_inode;
1371	  FAR uart_dev_t   *dev      = inode->i_private;
1372	  ssize_t           nwritten = buflen;
1373	  bool              oktoblock;
1374	  irqstate_t        flags;
1375	  int               ret;
1376	  char              ch;
1377	
1378	  /* We may receive serial writes through this path from interrupt handlers
1379	   * and from debug output in the IDLE task!  In these cases, we will need to
1380	   * do things a little differently.
1381	   */
1382	
1383	  if (up_interrupt_context() || sched_idletask())
1384	    {
1385	#ifdef CONFIG_SERIAL_REMOVABLE
1386	      /* If the removable device is no longer connected, refuse to write to
1387	       * the device.
1388	       */
1389	
1390	      if (dev->disconnected)
1391	        {
1392	          return -ENOTCONN;
1393	        }
1394	#endif
1395	
1396	      flags = uart_spinlock(dev, false);
1397	      ret = uart_irqwrite(dev, buffer, buflen);
1398	      uart_spinunlock(dev, false, flags);
1399	
1400	      return ret;
1401	    }
1402	
1403	  /* Only one user can access dev->xmit.head at a time */
1404	
1405	  ret = nxmutex_lock(&dev->xmit.lock);
1406	  if (ret < 0)
1407	    {
1408	      /* A signal received while waiting for access to the xmit.head will
1409	       * abort the transfer.  After the transfer has started, we are
1410	       * committed and signals will be ignored.
1411	       */
1412	
1413	      return ret;
1414	    }
1415	
1416	#ifdef CONFIG_SERIAL_REMOVABLE
1417	  /* If the removable device is no longer connected, refuse to write to the
1418	   * device.  This check occurs after taking the xmit.lock because the
1419	   * disconnection event might have occurred while we were waiting for
1420	   * access to the transmit buffers.
1421	   */
1422	
1423	  if (dev->disconnected)
1424	    {
1425	      nxmutex_unlock(&dev->xmit.lock);
1426	      return -ENOTCONN;
1427	    }
1428	#endif
1429	
1430	  /* Can the following loop block, waiting for space in the TX
1431	   * buffer?
1432	   */
1433	
1434	  oktoblock = ((filep->f_oflags & O_NONBLOCK) == 0);
1435	
1436	  /* Loop while we still have data to copy to the transmit buffer.
1437	   * we add data to the head of the buffer; uart_xmitchars takes the
1438	   * data from the end of the buffer.
1439	   */
1440	
1441	  uart_disabletxint(dev);
1442	  for (; buflen; buflen--)
1443	    {
1444	      ch  = *buffer++;
1445	      ret = OK;
1446	
1447	      /* Do output post-processing */
1448	
1449	      if ((dev->tc_oflag & OPOST) != 0)
1450	        {
1451	          /* Mapping CR to NL? */
1452	
1453	          if ((ch == '\r') && (dev->tc_oflag & OCRNL) != 0)
1454	            {
1455	              ch = '\n';
1456	            }
1457	
1458	          /* Are we interested in newline processing? */
1459	
1460	          if ((ch == '\n') && (dev->tc_oflag & (ONLCR | ONLRET)) != 0)
1461	            {
1462	              ret = uart_putxmitchar(dev, '\r', oktoblock);
1463	            }
1464	
1465	          /* Specifically not handled:
1466	           *
1467	           * OXTABS - primarily a full-screen terminal optimization
1468	           * ONOEOT - Unix interoperability hack
1469	           * OLCUC  - Not specified by POSIX
1470	           * ONOCR  - low-speed interactive optimization
1471	           */
1472	        }
1473	
1474	      /* Put the character into the transmit buffer */
1475	
1476	      if (ret >= 0)
1477	        {
1478	          ret = uart_putxmitchar(dev, ch, oktoblock);
1479	        }
1480	
1481	      /* uart_putxmitchar() might return an error under one of two
1482	       * conditions:  (1) The wait for buffer space might have been
1483	       * interrupted by a signal (ret should be -EINTR), (2) if
1484	       * CONFIG_SERIAL_REMOVABLE is defined, then uart_putxmitchar()
1485	       * might also return if the serial device was disconnected
1486	       * (with -ENOTCONN), or (3) if O_NONBLOCK is specified, then
1487	       * then uart_putxmitchar() might return -EAGAIN if the output
1488	       * TX buffer is full.
1489	       */
1490	
1491	      if (ret < 0)
1492	        {
1493	          /* POSIX requires that we return -1 and errno set if no data was
1494	           * transferred.  Otherwise, we return the number of bytes in the
1495	           * interrupted transfer.
1496	           */
1497	
1498	          if (buflen < (size_t)nwritten)
1499	            {
1500	              /* Some data was transferred.  Return the number of bytes that
1501	               * were successfully transferred.
1502	               */
1503	
1504	              nwritten -= buflen;
1505	            }
1506	          else
1507	            {
1508	              /* No data was transferred. Return the negated errno value.
1509	               * The VFS layer will set the errno value appropriately).
1510	               */
1511	
1512	              nwritten = ret;
1513	            }
1514	
1515	          break;
1516	        }
1517	    }
1518	
1519	  if (dev->xmit.head != dev->xmit.tail)
1520	    {
1521	#ifdef CONFIG_SERIAL_TXDMA
1522	      flags = uart_spinlock(dev, true);
1523	      uart_dmatxavail(dev);
1524	      uart_spinunlock(dev, true, flags);
1525	#endif
1526	      uart_enabletxint(dev);

1526	      uart_enabletxint(dev);
1527	    }
1528	
1529	  nxmutex_unlock(&dev->xmit.lock);
1530	  return nwritten;
1531	}
