402	static inline ssize_t uart_irqwrite(FAR uart_dev_t *dev,
403	                                    FAR const char *buffer,
404	                                    size_t buflen)
405	{
406	  size_t tail = 0;
407	  size_t head = buflen;
408	
409	  /* Do output post-processing */
410	
411	  if ((dev->tc_oflag & OPOST) != 0)
412	    {
413	      for (head = 0; head < buflen; head++)
414	        {
415	          int ch = buffer[head];
416	
417	          /* Mapping CR to NL? */
418	
419	          if ((ch == '\r') && (dev->tc_oflag & OCRNL) != 0)
420	            {
421	              uart_putchars(dev, &buffer[tail], head - tail);
422	              uart_putchars(dev, "\n", 1);
423	              tail = head + 1;
424	            }
425	
426	          /* Are we interested in newline processing? */
427	
428	          if ((ch == '\n') && (dev->tc_oflag & (ONLCR | ONLRET)) != 0)
429	            {
430	              uart_putchars(dev, &buffer[tail], head - tail);
431	              uart_putchars(dev, "\r", 1);
432	              tail = head;
433	            }
434	        }
435	    }
436	
437	  /* Output the character, using the low-level direct UART interfaces */
438	
439	  uart_putchars(dev, &buffer[tail], head - tail);
440	  return buflen;
441	}
