318	  usb_serial_jtag_ll_ena_intr_mask(USB_SERIAL_JTAG_INTR_SERIAL_OUT_RECV_PKT);
319	
320	  /* Try to attach the IRQ to a CPU int */
321	
322	  priv->cpuint = esp_setup_irq(priv->source,
323	                               ESP_IRQ_PRIORITY_DEFAULT,
324	                               ESP_IRQ_TRIGGER_LEVEL,
325	                               esp_interrupt,
326	                               dev);
327	  if (priv->cpuint < 0)
328	    {
329	      return priv->cpuint;
330	    }
331	
332	  /* Attach and enable the IRQ */
333	
334	  if (priv->cpuint >= 0)
