369	/****************************************************************************

547	 * Name: riscv_dispatch_irq
548	 *
549	 * Description:
550	 *   Process interrupt and its callback function.
551	 *
552	 * Input Parameters:
553	 *   mcause        - RISC-V "mcause" register.
554	 *   regs          - Saved registers reference.
555	 *
556	 * Returned Value:
557	 *   None.
558	 *
559	 ****************************************************************************/
560	
561	IRAM_ATTR void *riscv_dispatch_irq(uintreg_t mcause, uintreg_t *regs)
562	{
563	  /* Storm counter + latched storm mcause: plain RAM writes (never printed,
564	   * never block), so a reset + read tells us whether the CPU was spinning in
565	   * a dispatch storm and which trap source it was.  Addresses:
566	   * 0x5010ffe4 = storm counter (0x5010ffe0 = app marker, 0x5010fff0 = boot/
567	   * driver marker, 0x5010ffe8 = mcause latched when counter first exceeds
568	   * 50000; esp_bringup zeroes counter+latch after dumping, so the latch
569	   * always captures the PREVIOUS run's storm source and survives reset). */
570	  {
571	    volatile uint32_t *cnt = (volatile uint32_t *)0x5010ffe4;
572	    volatile uint32_t *lc = (volatile uint32_t *)0x5010ffe8;
573	    volatile uint32_t *irq_lc = (volatile uint32_t *)0x5010ffec;
574	    *cnt = *cnt + 1;
575	    if (*cnt > 1000 && *lc == 0)
576	      {
577	        *lc = (uint32_t)mcause;
578	        /* Resolve the storm cpuint back to an IRQ.  If the interrupting
579	         * peripheral was allocated via ESP-HAL's esp_intr_alloc_* (jpeg,
580	         * dma2d) instead of NuttX's esp_setup_irq, no handle was ever put
581	         * in g_handle_map, so this returns -1 (0xffffffff) and dispatch can
582	         * never service the interrupt -> level-triggered storm. */
583	        if ((RISCV_IRQ_BIT & mcause) != 0)
584	          {
585	            uint8_t cpuint = (uint8_t)((mcause & VECTORS_MCAUSE_REASON_MASK) -
586	                                       RV_EXTERNAL_INT_OFFSET);
587	            *irq_lc = (uint32_t)esp_cpuint_to_irq(cpuint, this_cpu());
588	          }
589	        else
590	          {
591	            *irq_lc = 0xffffffffu;
592	          }
593	      }
594	  }
595	
596	  /* Last-16-trap mcause ring at 0x5010fe00..0x5010fe3c, head index at
597	   * 0x5010fe40.  Survives warm reset; the M dump prints it so we can see
598	   * whether the storm is one interrupt repeating or a mix of traps. */
599	  {
600	    volatile uint32_t *ring = (volatile uint32_t *)0x5010fe00;
601	    volatile uint32_t *head = (volatile uint32_t *)0x5010fe40;
602	    uint32_t h = *head;
603	    ring[(h & 0xF)] = (uint32_t)mcause;
604	    *head = h + 1;
605	  }
606	
607	  /* One-shot probe: armed right before the JPEG up_irq_restore re-enables
608	   * MIE.  Prints the first dispatched interrupt/exception mcause so we can
609	   * tell an ISR storm / trap apart from a stuck main flow. */
610	  extern volatile int g_arm_dbg;
611	  extern void up_putc(int ch);
612	  static const char hex[] = "0123456789ABCDEF";
613	  if (g_arm_dbg)
614	    {
615	      g_arm_dbg = 0;
616	      up_putc('T'); up_putc(hex[(mcause >> 28) & 0xF]); up_putc(hex[(mcause >> 24) & 0xF]);
617	      up_putc(hex[(mcause >> 20) & 0xF]); up_putc(hex[(mcause >> 16) & 0xF]);
618	      up_putc(hex[(mcause >> 12) & 0xF]); up_putc(hex[(mcause >> 8) & 0xF]);
619	      up_putc(hex[(mcause >> 4) & 0xF]);  up_putc(hex[mcause & 0xF]); up_putc(' ');
620	    }
621	
622	  int irq;
623	  bool is_irq = (RISCV_IRQ_BIT & mcause) != 0;
624	  bool is_edge = false;
625	  int cpu = this_cpu();
626	
627	  if (is_irq)
628	    {
629	      uint8_t cpuint = (mcause & VECTORS_MCAUSE_REASON_MASK) -
630	                       RV_EXTERNAL_INT_OFFSET;
631	
632	      DEBUGASSERT(cpuint >= 0 && cpuint < ESP_NCPUINTS);
633	
634	      irq = esp_cpuint_to_irq(cpuint, cpu);
635	
636	      if (irq < 0)
637	        {
638	          /* No handle in NuttX's g_handle_map.  Interrupts allocated
639	           * through ESP-HAL's esp_intr_alloc_* (jpeg, dma2d) register
640	           * their handler in the ESP-HAL table (s_intr_handlers,
641	           * riscv/interrupt.c) instead of g_handle_map.  Call that
642	           * handler directly -- its ISR clears the level source, so
643	           * skipping it would leave the line asserted forever and
644	           * re-trigger this dispatch (level-triggered storm).
645	           */
646	
647	          intr_handler_t hal_handler = intr_handler_get(cpuint);
648	          if (hal_handler != NULL)
649	            {
650	              (*hal_handler)(intr_handler_get_arg(cpuint));
651	              return regs;
652	            }
653	
654	          irqwarn("No IRQ found for cpuint=%d cpu=%d\n", cpuint, cpu);
655	          return regs;
656	        }
657	
658	#ifdef CONFIG_ESPRESSIF_IRAM_ISR_DEBUG
659	      /* Check if non-IRAM interrupts are disabled */
660	
661	      if (esp_intr_noniram_is_disabled(cpu))
662	        {
663	          /* Sum-up the IRAM-enabled counter associated with the IRQ */
664	
665	          esp_irq_iram_interrupt_record(irq, this_cpu());
666	        }
667	#endif
668	
669	      is_edge = esprv_int_get_type(cpuint) != INTR_TYPE_LEVEL;
670	      if (is_edge)
671	        {
672	          /* Clear edge interrupts. */
673	
674	          esp_cpu_intr_edge_ack(cpuint);
675	        }
676	    }
677	  else
678	    {
679	      /* It's exception */
680	
681	      irq = mcause &
682	            (VECTORS_MCAUSE_INTBIT_MASK | VECTORS_MCAUSE_REASON_MASK);
683	    }
684	
685	  regs = riscv_doirq(irq, regs);
686	
687	  return regs;
688	}
