491	static void ESP_INTR_IRAM_ATTR shared_intr_isr(void *arg)
492	{
493	    vector_desc_t *vd = (vector_desc_t*)arg;
494	    shared_vector_desc_t *sh_vec = vd->shared_vec_info;
495	    (*((volatile uint32_t *)0x5010ffd8))++;  /* shared_intr_isr run counter */
496	    *((volatile uint32_t *)0x5010ffdc) = (uint32_t)vd->intno;  /* which CPU int */
497	    *((volatile uint32_t *)0x5010ffbc) = (uint32_t)vd->flags;  /* vector flags */
498	    if (sh_vec) {
499	        *((volatile uint32_t *)0x5010ffc8) = (uint32_t)sh_vec->source;
500	        *((volatile uint32_t *)0x5010ffc4) = sh_vec->statusreg ?
501	            (uint32_t)*sh_vec->statusreg : 0xffffffffu;
502	        *((volatile uint32_t *)0x5010ffc0) = (uint32_t)sh_vec->statusmask;
503	    }
504	    /* Per-call storm state snapshot (warm-reset markers; survives the lossy
505	     * console).  Updated every call so the M dump after a hard reset shows the
506	     * state at the END of the storm.  0x5010ff00..0x5010ff28. */
507	    {
508	        volatile uint32_t *clic = (volatile uint32_t *)0x20801000;
509	        volatile uint32_t *jp   = (volatile uint32_t *)0x50086000;
510	        volatile uint32_t *m = (volatile uint32_t *)0x5010ff00;
511	        uint32_t mc;
