515	        m[0x08/4] = clic[5];                         /* CLIC int5 */
516	        m[0x0c/4] = *((volatile uint32_t *)0x20800000); /* CLICCFG: validate base (NLBITS=bit4:1) */
517	        m[0x10/4] = *((volatile uint32_t *)0x20800004); /* CLICINFO */
518	        uint32_t st;
519	        asm volatile("csrr %0, 0x300" : "=r"(st));   /* mstatus */
520	        m[0x14/4] = st;
521	        m[0x18/4] = jp[0x38/4];  /* jpeg int_raw */
522	        m[0x1c/4] = jp[0x3c/4];  /* jpeg int_ena */
523	        m[0x20/4] = jp[0x40/4];  /* jpeg int_st */
524	        /* source that actually matched the statusmask this call, else none */
525	        uint32_t matched = 0xffffffffu;
526	        shared_vector_desc_t *s2 = vd->shared_vec_info;
527	        while (s2) {
528	            if (!s2->disabled && (s2->statusreg == NULL || (*s2->statusreg & s2->statusmask))) {
529	                matched = (uint32_t)s2->source;
530	                break;
531	            }
532	            s2 = s2->next;
533	        }
534	        m[0x24/4] = matched;
535	    }
536	    /* Throttled heartbeat: print 'k' every 1024th call so the console stays
537	     * readable while still confirming the storm persists. */
538	    {
539	        static uint32_t s_kc;
540	        if ((s_kc++ & 0x3ff) == 0) dbg_putc('k');
541	    }
542	    static int s_sh_once = 0;
543	    if (!s_sh_once) {
544	        s_sh_once = 1;
545	        up_putc('S'); dbgm_hx((uint32_t)vd->intno); up_putc('f'); dbgm_hx((uint32_t)vd->flags);
546	        {
547	            shared_vector_desc_t *sv = vd->shared_vec_info;
548	            int n = 0;
549	            while (sv && n < 8) {
550	                up_putc('[');
551	                dbgm_hx((uint32_t)sv->source);          /* source id */
552	                up_putc(':');
553	                dbgm_hx(sv->statusreg ? (uint32_t)*sv->statusreg : 0xffffffffu);  /* reg value */
554	                up_putc(':');
555	                dbgm_hx((uint32_t)sv->statusmask);      /* mask */
556	                up_putc(']');
557	                sv = sv->next; n++;
558	            }
559	        }
560	        {
561	            /* reverse scan int_map: which sources route to this intno.
562	             * Latch the first two found and the count into warm-reset markers
563	             * (console is lossy during the storm). */
564	            volatile uint32_t *map = (volatile uint32_t *)0x500D6000;  /* INTR_CORE0_BASE */
565	            int s, cnt = 0;
566	            uint32_t f1 = 0xffffffff, f2 = 0xffffffff;
