578	            *((volatile uint32_t *)0x5010ff94) = f2;
579	            *((volatile uint32_t *)0x5010ff98) = (uint32_t)cnt;
580	        }
581	        {
582	            /* raw int_map values for key sources + CLIC int5 register */
