593	            *((volatile uint32_t *)0x5010ff74) = clic[18];  /* CLIC int18 (boot cpuint2) */
594	            *((volatile uint32_t *)0x5010ff78) = clic[19];  /* CLIC int19 (boot cpuint3) */
