static int esp_interrupt(int irq, void *context, void *arg)
{
  struct uart_dev_s *dev = (struct uart_dev_s *)arg;
  uint32_t int_status = usb_serial_jtag_ll_get_intsts_mask();

  /* Console ISR diagnostic (RAM slots survive warm reset; read in the boot
   * M dump's C: field): 0x5010ffa0 = total ISR entries, 0x5010ffa4 =
   * SERIAL_IN_EMPTY branches, 0x5010ffa8 = last int_st, 0x5010ffac = last
   * int_ena.  This distinguishes "ISR stopped firing" (counts frozen, ena
   * IN_EMPTY clear) from "ISR firing but not draining" (counts climbing). */

  *((volatile uint32_t *)0x5010ffa0) += 1;

  /* Send buffer has room and can accept new data. */

  if ((int_status & USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY) != 0)
    {
      *((volatile uint32_t *)0x5010ffa4) += 1;
      *((volatile uint32_t *)0x5010ffa8) = int_status;
      *((volatile uint32_t *)0x5010ffac) =
        usb_serial_jtag_ll_get_intr_ena_status();
      usb_serial_jtag_ll_clr_intsts_mask(
        USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY);
      uart_xmitchars(dev);
    }

