  int nexthead;
  int ret;

  /* Loop until we are able to add the character to the TX buffer. */

  for (; ; )
    {
      /* Increment to see what the next head pointer will be.
       * We need to use the "next" head pointer to determine when the
       * circular buffer would overrun
